    iframeDoc.close();

    iframe.onload = () => {
      iframe.contentWindow.focus();
      iframe.contentWindow.print();
      setTimeout(() => {
        document.body.removeChild(iframe);
      }, 1000);
    };
  } catch (error) {
    showError(`Failed to print report: ${error.message}`);
  }
};


const budgets = ref([])
const isBudgetsloading = ref(false)

const getBudgets = async (id) => {
  isBudgetsloading.value = true;
  budgets.value = [];

  try {
    const response = await axiosInstance.get(`get-budgets?project_id=${id}`);
    const realBudgets = response.data.filter(b => b.status === "closed");
    budgets.value = realBudgets;
  } catch (error) {
    console.log(error);
    showError(error.message);
  } finally {
    isBudgetsloading.value = false;
  }
};


watch(store, (newVal) => {
    if (newVal && newVal.id === -1 ) { 
        getBudgets(selectedProjectId.value); 
    }
});

